import{_ as h,C as c,o as i,c as p,an as s,b as n,w as r,a as t,E as l,ao as d,j as a}from"./chunks/framework.BR9x3YLT.js";const A=JSON.parse('{"title":"Design philosophy","description":"","frontmatter":{},"headers":[],"relativePath":"for_tm5_gchp_users/philosophy.md","filePath":"for_tm5_gchp_users/philosophy.md","lastUpdated":null}'),u={name:"for_tm5_gchp_users/philosophy.md"};function g(m,e,y,f,b,v){const o=c("Mermaid");return i(),p("div",null,[e[2]||(e[2]=s('<h1 id="Design-philosophy" tabindex="-1">Design philosophy <a class="header-anchor" href="#Design-philosophy" aria-label="Permalink to &quot;Design philosophy {#Design-philosophy}&quot;">​</a></h1><p>AtmosTransport sits in the same family as <strong>TM5-4DVAR</strong> and the <strong>GEOS-Chem High Performance / GCHP CTM</strong> lineage: an <em>offline</em> tracer transport model driven by pre-computed meteorology. If you are fluent in either of those codes, most of the physics terms map across unchanged. What differs is the <em>engineering shape</em> — the contract between preprocessing and runtime, how operators dispatch, and how the work spreads across CPU / CUDA / Metal from a single source tree.</p><p>This page lays out the design choices so you can carry your mental model in. The next pages drill into how that model is realized for binaries, operators, adjoints, and the kernel architecture.</p><h2 id="The-one-line-summary" tabindex="-1">The one-line summary <a class="header-anchor" href="#The-one-line-summary" aria-label="Permalink to &quot;The one-line summary {#The-one-line-summary}&quot;">​</a></h2><blockquote><p>Pre-compute mass-conserving daily binaries off-line; memory-map them at runtime; dispatch every physics operator through Julia&#39;s type system; write one kernel per loop and let <code>KernelAbstractions.jl</code> retarget it to CPU, CUDA, or Metal.</p></blockquote><p>Everything in the docs is a consequence of that line.</p><h2 id="Where-we-sit-relative-to-TM5-and-GCHP" tabindex="-1">Where we sit relative to TM5 and GCHP <a class="header-anchor" href="#Where-we-sit-relative-to-TM5-and-GCHP" aria-label="Permalink to &quot;Where we sit relative to TM5 and GCHP {#Where-we-sit-relative-to-TM5-and-GCHP}&quot;">​</a></h2>',7)),(i(),n(d,null,{default:r(()=>[l(o,{id:"mermaid-23",class:"mermaid-diagram",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20TM5%0A%20%20%20%20%20%20%20%20T1%5BECMWF%20GRIB%5D%20--%3E%20T2%5Btm5-meteo%3Cbr%2F%3Eboundary%20archive%5D%0A%20%20%20%20%20%20%20%20T2%20--%3E%20T3%5BTM5%20CTM%3Cbr%2F%3EFortran%2C%20MPI%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20GCHP%0A%20%20%20%20%20%20%20%20G1%5BGEOS%20NetCDF%3Cbr%2F%3E%2B%20HEMCO%20emissions%5D%20--%3E%20G2%5BMAPL%20ExtData%3Cbr%2F%3Econnectors%5D%0A%20%20%20%20%20%20%20%20G2%20--%3E%20G3%5BGCHP%20CTM%3Cbr%2F%3EFortran%2C%20FV3%20dycore%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20AtmosTransport%0A%20%20%20%20%20%20%20%20A1%5BERA5%20spectral%20GRIB%3Cbr%2F%3Eor%20GEOS%20native%20NetCDF%5D%20--%3E%20A2%5BDaily%20transport%20binary%3Cbr%2F%3EJSON%20header%20%2B%20flat%20payload%5D%0A%20%20%20%20%20%20%20%20A2%20--%3E%20A3%5BAtmosTransport%20runtime%3Cbr%2F%3EJulia%20%2B%20KernelAbstractions%5D%0A%20%20%20%20end%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=s('<table tabindex="0"><thead><tr><th style="text-align:right;">Concern</th><th style="text-align:right;">TM5-4DVAR</th><th style="text-align:right;">GCHP CTM</th><th style="text-align:right;">AtmosTransport</th></tr></thead><tbody><tr><td style="text-align:right;">Source language</td><td style="text-align:right;">Fortran 90 + MPI</td><td style="text-align:right;">Fortran 90 + MAPL + ESMF</td><td style="text-align:right;">Julia + KernelAbstractions</td></tr><tr><td style="text-align:right;">Native grid</td><td style="text-align:right;">Reduced Gaussian (TM5) or LL</td><td style="text-align:right;">Cubed-sphere (FV3)</td><td style="text-align:right;">Lat-Lon, Reduced Gaussian, Cubed-sphere</td></tr><tr><td style="text-align:right;">Met-data ingestion</td><td style="text-align:right;">tm5-meteo boundary archive</td><td style="text-align:right;">MAPL ExtData NetCDF connectors</td><td style="text-align:right;">One daily binary per day</td></tr><tr><td style="text-align:right;">Advection core</td><td style="text-align:right;">Russell-Lerner slopes + Strang split</td><td style="text-align:right;">PPM (Lin-Rood) with FV substepping</td><td style="text-align:right;">Slopes / PPM / Lin-Rood (CS) via type dispatch</td></tr><tr><td style="text-align:right;">Convection</td><td style="text-align:right;">Tiedtke/SiBJK two-side updraft/downdraft</td><td style="text-align:right;">RAS / SHOC / GMAO depending on collection</td><td style="text-align:right;">TM5 four-field <em>or</em> GCHP-style CMFMC</td></tr><tr><td style="text-align:right;">Vertical diffusion</td><td style="text-align:right;">Holtslag–Boville non-local</td><td style="text-align:right;">GCHP/VDIFF local Beljaars–Viterbo</td><td style="text-align:right;">Beljaars–Viterbo and local Holtslag–Boville Kz fields</td></tr><tr><td style="text-align:right;">Mass basis</td><td style="text-align:right;">Moist (with explicit qv bookkeeping)</td><td style="text-align:right;">Moist + dry conversions per-operator</td><td style="text-align:right;"><strong>Dry by default</strong>, basis is a <em>type parameter</em></td></tr><tr><td style="text-align:right;">Multi-tracer</td><td style="text-align:right;">Tracer loop <em>inside</em> each operator</td><td style="text-align:right;">Tracer loop <em>inside</em> FV step (PPM × Nt)</td><td style="text-align:right;">Packed tracer dimension in LL and CS split-sweep kernels</td></tr><tr><td style="text-align:right;">Adjoint</td><td style="text-align:right;">TM5-4DVAR (hand-coded)</td><td style="text-align:right;">GIGC adjoint (separate fork)</td><td style="text-align:right;">Tape + checkpoint + replay; surface-emission footprints and a CS 4D-Var scaffold</td></tr><tr><td style="text-align:right;">Hardware</td><td style="text-align:right;">CPU clusters</td><td style="text-align:right;">CPU clusters (some GPU effort upstream)</td><td style="text-align:right;">Single-node multi-GPU (CUDA / Metal) and CPU; one source tree</td></tr></tbody></table><p>The differences are deliberate; the similarities are deliberate too. We deviate where Julia + KA pays off, and converge where the physics community has settled (operator naming, basis conventions, mass-flux sign conventions).</p><h2 id="Design-tenets" tabindex="-1">Design tenets <a class="header-anchor" href="#Design-tenets" aria-label="Permalink to &quot;Design tenets {#Design-tenets}&quot;">​</a></h2><h3 id="1.-The-binary-is-the-contract" tabindex="-1">1. The binary is the contract <a class="header-anchor" href="#1.-The-binary-is-the-contract" aria-label="Permalink to &quot;1. The binary is the contract {#1.-The-binary-is-the-contract}&quot;">​</a></h3><p>Off-line preprocessing produces a single binary per day. That binary fully specifies every field the runtime needs: air mass, horizontal and vertical mass fluxes, surface pressure, optional moist physics fields. A padded JSON header declares topology, basis, vertical coordinate, substep schedule, and which optional sections are present. The runtime&#39;s job is to memory-map the file and stream over windows; nothing about the model is configured by reading raw met files at run time.</p><p>TM5 users will recognize this as a hardened version of the <em>boundary archive</em>. GCHP users will recognize it as the moral equivalent of the MAPL ExtData connector layer collapsed into a single deterministic file with a typed schema. Both communities have lost weeks to sample-timing bugs or import-order issues; the binary removes that class of bug by design.</p><p>See <a href="./binary_pipeline">The binary pipeline</a> for what&#39;s inside, what the gate checks, and why the trade-offs work.</p><h3 id="2.-Type-dispatch,-not-configuration-strings" tabindex="-1">2. Type dispatch, not configuration strings <a class="header-anchor" href="#2.-Type-dispatch,-not-configuration-strings" aria-label="Permalink to &quot;2. Type dispatch, not configuration strings {#2.-Type-dispatch,-not-configuration-strings}&quot;">​</a></h3><p>Every operator is an abstract type with a <code>No&lt;Operator&gt;</code> default. The runtime&#39;s job is to call <code>apply!(state, ..., op, dt)</code>; Julia picks the method at compile time based on the type of <code>op</code>. There is no <code>if scheme == &quot;ppm&quot;</code> ladder anywhere in the inner loop. Adding a new advection scheme is a matter of subtyping <code>AbstractAdvectionScheme</code> and writing the kernels — no central registry to edit, no configuration-parser changes required after the TOML parse-time mapping.</p><p>This is the single biggest difference from TM5 / GCHP. Both codes carry years of <code>if (USE_FOO)</code> branches that have to be threaded down to the kernel call sites; the cost is paid every step. In Julia those branches dissolve at compile time and the kernel that runs is exactly the kernel for the configured operator.</p><p>See <a href="./operators_on_binaries">Operators on top of the binary</a>.</p><h3 id="3.-One-kernel,-three-backends" tabindex="-1">3. One kernel, three backends <a class="header-anchor" href="#3.-One-kernel,-three-backends" aria-label="Permalink to &quot;3. One kernel, three backends {#3.-One-kernel,-three-backends}&quot;">​</a></h3><p>Every hot loop is written once as a <code>KernelAbstractions.@kernel</code>. The same function targets CPU, NVIDIA CUDA, and Apple Silicon Metal, selected by the <code>[architecture].backend</code> line in the TOML. There is no &quot;GPU version&quot; of any operator that is separately maintained from the &quot;CPU version&quot;. Workspace structures are parametric on the array type so the same struct holds <code>Array{Float32}</code> on CPU and <code>CuArray{Float32}</code> on CUDA without duplication.</p><p>See <a href="./kernel_architecture">Kernel architecture</a>.</p><h3 id="4.-Multi-tracer-kernels-by-default" tabindex="-1">4. Multi-tracer kernels by default <a class="header-anchor" href="#4.-Multi-tracer-kernels-by-default" aria-label="Permalink to &quot;4. Multi-tracer kernels by default {#4.-Multi-tracer-kernels-by-default}&quot;">​</a></h3><p>AtmosTransport&#39;s structured and cubed-sphere split-sweep paths store tracer mass in a packed fourth dimension. The six directional legs of one advection palindrome therefore launch per direction, not per tracer, while still doing the flux work and memory traffic required for every tracer. Lin-Rood uses a different horizontal implementation and should be benchmarked separately. See <a href="./kernel_architecture">Kernel architecture</a> for the exact data layout and profiling tools.</p><h3 id="5.-Mass-conservation-is-type-level" tabindex="-1">5. Mass conservation is type-level <a class="header-anchor" href="#5.-Mass-conservation-is-type-level" aria-label="Permalink to &quot;5. Mass conservation is type-level {#5.-Mass-conservation-is-type-level}&quot;">​</a></h3><p>Dry-basis vs moist-basis is a Julia type parameter (<code>State{DryBasis}</code> vs <code>State{MoistBasis}</code>); a binary advertises its basis in the header; the runtime refuses to load a mismatched binary at construction time. The <code>cm</code> (vertical mass flux) field in every binary is closed against the explicit <code>dm</code> (per-substep mass delta) field at write time, with a write-time replay gate that evolves the mass forward one window and checks bit-level closure. A runtime that opens a binary whose write-time gate failed will refuse to step.</p><p>See <a href="./../theory/mass_conservation">Mass conservation theory</a> and the <a href="./../concepts/binary_format">Binary format reference</a>.</p><h3 id="6.-Adjoints-are-a-layer,-not-a-fork" tabindex="-1">6. Adjoints are a layer, not a fork <a class="header-anchor" href="#6.-Adjoints-are-a-layer,-not-a-fork" aria-label="Permalink to &quot;6. Adjoints are a layer, not a fork {#6.-Adjoints-are-a-layer,-not-a-fork}&quot;">​</a></h3><p>Tape recording and reverse replay live in <code>src/Tape/</code>, <code>src/Adjoints/</code>, and <code>src/Footprint/</code>. The footprint forward pass records typed operator data; the reverse pass walks those records backwards with operator-specific adjoint kernels. The shipped consumers are surface-emission footprints and the cubed-sphere 4D-Var cost/gradient and optimizer workflows. A small inversion script provides a runnable driver, but the reverse operators remain in the same source tree as the forward code.</p><p>See <a href="./adjoints">Adjoints on top of the binary</a>.</p><h2 id="What-you-give-up" tabindex="-1">What you give up <a class="header-anchor" href="#What-you-give-up" aria-label="Permalink to &quot;What you give up {#What-you-give-up}&quot;">​</a></h2><p>To make the binary-as-contract pattern work, three things go away:</p><ul><li><p><strong>Online dynamics.</strong> AtmosTransport cannot run a free-running GCM; it requires precomputed mass fluxes. If you need radiation, convection-resolving cloud microphysics, or an interactive surface scheme, this is the wrong tool.</p></li><li><p><strong>Per-step preprocessing.</strong> Reading raw ERA5 spectral coefficients or raw GEOS NetCDF <em>at every met step</em> is not supported. We commit to preprocessing the entire day up-front.</p></li><li><p><strong>Stateful in-memory data services.</strong> No MAPL, no FMS-style registries. Everything the runtime needs is on disk in the binary.</p></li></ul><p>In return, you get a runtime that:</p><ul><li><p>reads one self-describing transport product instead of reconstructing a forcing schema at every model step;</p></li><li><p>targets CPU, CUDA, and Metal from the same operator implementations;</p></li><li><p>exposes window loading, backend copies, and physics as separate timing sections; and</p></li><li><p>carries the numerical schedule and mass-basis contract with the data.</p></li></ul><h2 id="Reading-order-from-here" tabindex="-1">Reading order from here <a class="header-anchor" href="#Reading-order-from-here" aria-label="Permalink to &quot;Reading order from here {#Reading-order-from-here}&quot;">​</a></h2>',28)),(i(),n(d,null,{default:r(()=>[l(o,{id:"mermaid-298",class:"mermaid-diagram",graph:"flowchart%20TD%0A%20%20%20%20P%5BPhilosophy%5D%20--%3E%20B%5BBinary%20pipeline%5D%0A%20%20%20%20B%20--%3E%20O%5BOperators%20on%20the%20binary%5D%0A%20%20%20%20B%20--%3E%20K%5BKernel%20architecture%5D%0A%20%20%20%20O%20--%3E%20A%5BAdjoints%5D%0A%20%20%20%20K%20--%3E%20A%0A"})]),fallback:r(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=a("p",null,[t("If you have a TM5 background, the next page that moves the needle fastest is usually "),a("a",{href:"./binary_pipeline"},"The binary pipeline"),t(' — your mental model of "the boundary archive" maps almost directly.')],-1)),e[5]||(e[5]=a("p",null,[t("If you have a GCHP background, jump to "),a("a",{href:"./operators_on_binaries"},"Operators on top of the binary"),t(" first; the PPM / palindrome / FV vocabulary will already be familiar, and the section spells out the small but important differences from Lin-Rood-as-implemented-in-FV3.")],-1)),e[6]||(e[6]=a("p",null,[t("Either way, finish with "),a("a",{href:"./kernel_architecture"},"Kernel architecture"),t(" to understand why the runtime can sustain GPU peak throughput while keeping a single source tree.")],-1))])}const k=h(u,[["render",g]]);export{A as __pageData,k as default};
